"""Build or check the single-file manuscript using only the standard library.

Run from any directory: python paper/build_standalone.py
Edit main.tex, references.bib, or the generators, not timegym.tex.
"""

import argparse
from datetime import date
from pathlib import Path
import re


PAPER_DIR = Path(__file__).resolve().parent
BANNER = (
    "% Generated by paper/build_standalone.py from CITATION.cff, main.tex, references.bib, "
    "generated-*.tex and figures/*.tikz; edit the inputs instead.\n"
)


def read_bibliography(path: Path) -> dict[str, dict[str, str]]:
    """Read the bibliography's braced, one-field-per-line BibTeX subset."""
    entries: dict[str, dict[str, str]] = {}
    entry: dict[str, str] | None = None
    for number, line in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
        line = line.strip()
        if not line or line.startswith("%"):
            continue
        start = re.fullmatch(r"@(article|book|inproceedings|misc|manual)\{([\w-]+),", line)
        field = re.fullmatch(r"(\w+)\s*=\s*\{(.*)\},?", line)
        if start and entry is None:
            key = start[2]
            if key in entries:
                raise ValueError(f"Duplicate bibliography key: {key}")
            entry = entries[key] = {"type": start[1]}
        elif line == "}" and entry is not None:
            entry = None
        elif field and entry is not None:
            name, value = field[1].lower(), field[2]
            if name in entry:
                raise ValueError(f"Duplicate bibliography field {name}: {path}:{number}")
            depth = 0
            for token in re.finditer(r"\\.|[{}]", value):
                depth += 1 if token[0] == "{" else -1 if token[0] == "}" else 0
                if depth < 0:
                    break
            if depth:
                raise ValueError(f"Unbalanced bibliography braces: {path}:{number}")
            entry[name] = value
        else:
            raise ValueError(f"Unsupported bibliography syntax: {path}:{number}: {line}")
    if entry is not None:
        raise ValueError(f"Unclosed bibliography entry in {path}")
    return entries


def render_bibliography(manuscript: str, path: Path) -> str:
    """Render cited entries in author/title order, as requested by plain style."""
    entries = read_bibliography(path)
    cited = {key.strip() for group in re.findall(r"\\cite\{([^}]+)\}", manuscript)
             for key in group.split(",")}
    missing = cited - entries.keys()
    if missing:
        raise ValueError(f"Missing bibliography entries: {', '.join(sorted(missing))}")
    for key in sorted(cited):
        fields = entries[key]
        for required in ("title", "year", "url"):
            if not fields.get(required):
                raise ValueError(f"Missing {required} in bibliography entry {key}")
        if not (fields.get("author") or fields.get("organization")):
            raise ValueError(f"Missing author or organization in bibliography entry {key}")

    def sort_key(key: str) -> tuple[str, str, str]:
        fields = entries[key]
        author = fields.get("author", fields.get("organization", ""))
        return (re.sub(r"[^a-z0-9 ]", "", author.lower()),
                re.sub(r"[^a-z0-9 ]", "", fields["title"].lower()), key)

    lines = [rf"\begin{{thebibliography}}{{{len(cited)}}}"]
    for key in sorted(cited, key=sort_key):
        fields = entries[key]
        names = []
        for author in fields.get("author", fields.get("organization", "")).split(" and "):
            parts = author.split(", ", 1)
            names.append(f"{parts[1]} {parts[0]}" if len(parts) == 2 else author)
        authors = (", ".join(names[:-1]) + " and " + names[-1]) if len(names) > 1 else names[0]
        lines.extend([rf"\bibitem{{{key}}}", authors.rstrip(".") + ".",
                      rf"\href{{{fields['url']}}}{{{fields['title']}}}."])
        venue = fields.get("journal", fields.get("booktitle", ""))
        publication = rf"\emph{{{venue}}}" if venue else ""
        if fields["type"] == "book":
            if not fields.get("publisher"):
                raise ValueError(f"Missing publisher in bibliography entry {key}")
            publication = fields["publisher"]
        if "volume" in fields:
            publication += f", {fields['volume']}"
        if "number" in fields:
            publication += f"({fields['number']})"
        if "pages" in fields and "articleno" not in fields:
            publication += f", pp. {fields['pages']}"
        if "articleno" in fields:
            publication += f", Article {fields['articleno']}"
        if "numpages" in fields:
            publication += f", {fields['numpages']} pages"
        if "eprint" in fields:
            publication += f"arXiv:{fields['eprint']}"
        lines.append((publication + ", " if publication else "") + fields["year"] + ".")
        if "note" in fields:
            lines.append(fields["note"].rstrip(".") + ".")
        lines.append("")
    lines.append(r"\end{thebibliography}")
    return "\n".join(lines) + "\n"


def release_stamp(citation_path: Path) -> str:
    metadata = citation_path.read_text(encoding="utf-8")
    fields = {}
    for name in ("version", "date-released"):
        matches = re.findall(rf"^{name}: *([^\n]+)$", metadata, re.M)
        if len(matches) != 1:
            raise ValueError(f"Expected one {name} scalar in CITATION.cff")
        fields[name] = matches[0].strip().strip("\"'")
    if not re.fullmatch(r"\d+\.\d+\.\d+", fields["version"]):
        raise ValueError("Invalid CITATION.cff version")
    released = date.fromisoformat(fields["date-released"])
    return (rf"\date{{{released.isoformat()}\\\small TimeGym {fields['version']}"
            r"; working manuscript: reproducible controlled studies}")


def build(*, paper_dir: Path = PAPER_DIR) -> str:
    manuscript = (paper_dir / "main.tex").read_text(encoding="utf-8")
    if len(re.findall(r"^\\date\{.*\}$", manuscript, re.M)) != 1:
        raise ValueError("Expected one date line in main.tex")
    standalone = re.sub(r"^\\date\{.*\}$",
                        lambda _: release_stamp(paper_dir.parent / "CITATION.cff"),
                        manuscript, flags=re.M)
    for name, marker in (("generated-macros.tex", "MACROS"),
                         ("generated-results.tex", "RESULTS"),
                         ("generated-supplement.tex", "SUPPLEMENT")):
        results_path = paper_dir / name
        if not results_path.is_file():
            raise ValueError(f"Missing paper/{name}. Run and render both studies before building the manuscript.")
        start = f"% BEGIN GENERATED {marker}"
        end = f"% END GENERATED {marker}"
        if standalone.count(start) != 1 or standalone.count(end) != 1:
            raise ValueError(f"Expected exactly one generated-{marker.lower()} block in main.tex")
        before, remaining = standalone.split(start, 1)
        _, after = remaining.split(end, 1)
        standalone = before + start + "\n" + results_path.read_text(encoding="utf-8") + "\n" + end + after
    names = re.findall(r"% BEGIN VECTOR FIGURE ([a-z-]+)", standalone)
    if len(names) != len(set(names)):
        raise ValueError("Duplicate vector-figure identifiers")
    for name in names:
        start, end = f"% BEGIN VECTOR FIGURE {name}", f"% END VECTOR FIGURE {name}"
        if standalone.count(start) != 1 or standalone.count(end) != 1:
            raise ValueError(f"Expected one complete vector-figure block for {name}")
        figure = paper_dir / "figures" / f"{name}.tikz"
        if not figure.is_file():
            raise ValueError(f"Missing {figure.name}; run python paper/render_figures.py first")
        before, remaining = standalone.split(start, 1)
        _, after = remaining.split(end, 1)
        standalone = before + start + "\n" + figure.read_text(encoding="utf-8") + "\n" + end + after
    bibliography = "\\bibliographystyle{plain}\n\\bibliography{references}"
    if standalone.count(bibliography) != 1:
        raise ValueError("Expected one plain bibliography using references.bib in main.tex")
    standalone = standalone.replace(
        bibliography,
        "% BEGIN GENERATED BIBLIOGRAPHY\n"
        + render_bibliography(standalone, paper_dir / "references.bib")
        + "% END GENERATED BIBLIOGRAPHY",
    )
    return BANNER + standalone


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Report drift without writing files")
    args = parser.parse_args()
    try:
        standalone = build(paper_dir=PAPER_DIR)
    except (OSError, ValueError) as error:
        parser.exit(2, f"{error}\n")
    output = PAPER_DIR / "timegym.tex"
    if args.check:
        if not output.is_file() or output.read_bytes() != standalone.encode("utf-8"):
            print("Standalone manuscript is out of date. Run python paper/build_standalone.py")
            return 1
        print("Standalone manuscript is up to date.")
    else:
        output.write_bytes(standalone.encode("utf-8"))
        print(output)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
